//github.com/kojix2/adaptive.cr/blob/a90424fde27b39ea7a576900f8a50862c97d35f7/src/gui/launcher.cr#L5"},"def":{"name":"run","visibility":"Public","body":"begin\n  executable = File.join(File.dirname(Process.executable_path || PROGRAM_NAME), Profile.command)\n  directory = Dir.current\n  config : String | ::Nil = nil\n  information_only = false\n  parser = OptionParser.new do |options|\n    options.banner = \"Usage: #{Profile.command}-gui [options]\"\n    options.on(\"-c PATH\", \"--config=PATH\", \"Open a JSON configuration\") do |value| config = File.expand_path(value) end\n    options.on(\"--workdir=PATH\", \"Working directory for relative config paths\") do |value| directory = File.expand_path(value) end\n    options.on(\"--cli=PATH\", \"CLI executable (default: sibling binary)\") do |value| executable = File.expand_path(value) end\n    options.on(\"--version\", \"Show version\") do     puts(\"#{Profile.command}-gui #{Profile.version}\")\n    information_only = true\n end\n    options.on(\"-h\", \"--help\", \"Show help\") do     puts(options)\n    information_only = true\n end\n  end\n  parser.parse\n  if information_only\n    return\n  end\n  if ARGV.empty?\n  else\n    raise(\"Unexpected arguments: #{ARGV.join(\" \")}\")\n  end\n  UIng.init do\n    app = Window.new(executable, directory)\n    UIng.main_steps\n    begin\n      if path = config\n        app.load_config(path)\n      end\n      app.show\n      run_loop(app)\n    ensure\n      app.request_close\n      run_loop(app)\n    end\n  end\nrescue error\n  STDERR.puts(\"#{Profile.command}-gui: #{error.message}\")\n  exit(1)\nend"},"external_var":false}],"types":[{"html_id":"adaptive/NanoporeGUI/Document","path":"NanoporeGUI/Document.html","kind":"class","full_name":"NanoporeGUI::Document","name":"Document","abstract":false,"superclass":{"html_id":"adaptive/Reference","kind":"class","full_name":"Reference","name":"Reference"},"ancestors":[{"html_id":"adaptive/Reference","kind":"class","full_name":"Reference","name":"Reference"},{"html_id":"adaptive/Object","kind":"class","full_name":"Object","name":"Object"}],"locations":[{"filename":"src/gui/model.cr","line_number":7,"url":"https://github.com/kojix2/adaptive.cr/blob/a90424fde27b39ea7a576900f8a50862c97d35f7/src/gui/model.cr#L7"}],"repository_name":"adaptive","program":false,"enum":false,"alias":false,"const":false,"namespace":{"html_id":"adaptive/NanoporeGUI","kind":"module","full_name":"NanoporeGUI","name":"NanoporeGUI"},"doc":"Keep the complete document, including settings not exposed by the form.","summary":"<p>Keep the complete document, including settings not exposed by the form.</p>","constructors":[{"html_id":"new(text:String)-class-method","name":"new","abstract":false,"args":[{"name":"text","external_name":"text","restriction":"String"}],"args_string":"(text : String)","args_html":"(text : String)","location":{"filename":"src/gui/model.cr","line_number":10,"url":"https://github.com/kojix2/adaptive.cr/blob/a90424fde27b39ea7a576900f8a50862c97d35f7/src/gui/model.cr#L10"},"def":{"name":"new","args":[{"name":"text","external_name":"text","restriction":"String"}],"visibility":"Public","body":"_ = allocate\n_.initialize(text)\nif _.responds_to?(:finalize)\n  ::GC.add_finalizer(_)\nend\n_\n"},"external_var":false}],"instance_methods":[{"html_id":"get(key:String):JSON::Any-instance-method","name":"get","abstract":false,"args":[{"name":"key","external_name":"key","restriction":"String"}],"args_string":"(key : String) : JSON::Any","args_html":"(key : String) : JSON::Any","location":{"filename":"src/gui/model.cr","line_number":15,"url":"https://github.com/kojix2/adaptive.cr/blob/a90424fde27b39ea7a576900f8a50862c97d35f7/src/gui/model.cr#L15"},"def":{"name":"get","args":[{"name":"key","external_name":"key","restriction":"String"}],"return_type":"JSON::Any","visibility":"Public","body":"(key.split('.')).reduce(@value) do |node, part|\n  node.as_a? ? node[part.to_i] : (node[part]? || (JSON::Any.new(nil)))\nend"},"external_var":